先看實際輸出中的 `0.000000` 是如何產生的。
```cpp
#include <iostream>
#include <cmath>
#include <iomanip>

using namespace std;

int main() {
  double s, a;
  string u;

  cout << fixed << setprecision(6);

  while (cin >> s >> a >> u) {
    if (u == "min") {
      a *= 60;
    }
    a = fmod(a, 360);
    a = min(a, 360 - a);
    double r = s + 6440;
    double t = a * acos(-1.0) / 180;
    cout << r * t << " " << 2 * r * sin(t / 2) << "\n";
  }

  return 0;
}
```

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int T;
    cin >> T;
    string s;
    getline(cin, s);
    cout << fixed << setprecision(4);
    for (int k = 0; k < T; k++) {
        map<string, int> m;
        int n = 0;
        while (getline(cin, s) && s.empty()) {
        }
        if (cin || !s.empty()) {
            if (!s.empty()) {
                m[s]++;
                n++;
            }
            while (getline(cin, s) && !s.empty()) {
                m[s]++;
                n++;
            }
        }
        for (auto [name, v] : m)
            cout << name << " " << v * 100.0 / n << "\n";
    }
}
```

首先，`while (getline(cin, s) && s.empty()) {}` 這段 `while` 迴圈可能導致無窮迴圈。因為 `getline(cin, s)` 會讀取一行字串，但 `s.empty()` 的判斷會先檢查 `s` 是否為空字串。如果 `getline` 成功讀取了字串，但該字串恰好是空字串，`s.empty()` 就會返回 `true`，導致 `while` 迴圈停止。
因此，第一步是修改此 `while` 迴圈，使其只在 `getline` 讀取到有內容時才退出。
